cat > $TMPDIR/fz/new.py <<'EOF'
import sys, random, itertools, statistics
sys.path.insert(0,"<scratch>/runs/.work/e1f82c844a/repo"); import more_itertools as m
R=random.Random(2); fails=set()
for _ in range(3000):
    L=[R.randint(-4,6) for _ in range(R.randint(1,9))]
    if m.argmin(L)!=L.index(min(L)): fails.add(('argmin',tuple(L),m.argmin(L)))
    if m.argmax(L)!=L.index(max(L)): fails.add(('argmax',tuple(L),m.argmax(L)))
    got=list(m.running_median(L)); exp=[statistics.median(L[:i+1]) for i in range(len(L))]
    if got!=exp: fails.add(('running_median',tuple(L),tuple(got),tuple(exp)))
    idx=[R.randint(0,len(L)+1) for _ in range(3)]
    try: got=list(m.extract(L,idx))
    except Exception as e: got=type(e).__name__
    exp=[L[i] for i in idx if i<len(L)] if all(i<len(L) for i in idx) else 'partial'
    if exp!='partial' and got!=exp: fails.add(('extract',tuple(L),tuple(idx),str(got)))
    S=L[:5]
    exp=[p for p in itertools.permutations(S) if all(a!=b for a,b in zip(p,S))]
    got=list(m.derangements(S))
    if sorted(got)!=sorted(exp): fails.add(('derangements',tuple(S),len(got),len(exp)))
for f in sorted(fails)[:15]: print(f)
print(len(fails))
EOF
python3 -I $TMPDIR/fz/new.py

